-- Bulk corpus import (#890, D-053): corpus_import_cursor holds the resume point and counts of each dataset archive, corpus_ocr_queue the judgment pages without a text layer. Both are global (no workspace_id, no RLS). The two AWS Open Data sources are registered uncleared: staff clear them in the console before `system.corpus.bulk_import` reads anything. Additive only.
CREATE TABLE "corpus_import_cursor" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"source_id" text NOT NULL,
	"dataset" text NOT NULL,
	"court" text,
	"year" integer NOT NULL,
	"archive_key" text NOT NULL,
	"position" integer DEFAULT 0 NOT NULL,
	"status" text DEFAULT 'pending' NOT NULL,
	"rows_added" integer DEFAULT 0 NOT NULL,
	"duplicates_skipped" integer DEFAULT 0 NOT NULL,
	"failures" integer DEFAULT 0 NOT NULL,
	"bytes_stored" bigint DEFAULT 0 NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE TABLE "corpus_ocr_queue" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"judgment_id" uuid NOT NULL,
	"page_no" integer NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
ALTER TABLE "corpus_ocr_queue" ADD CONSTRAINT "corpus_ocr_queue_judgment_id_judgment_id_fk" FOREIGN KEY ("judgment_id") REFERENCES "public"."judgment"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE UNIQUE INDEX "corpus_import_cursor_archive_uq" ON "corpus_import_cursor" USING btree ("source_id","archive_key");--> statement-breakpoint
CREATE INDEX "corpus_import_cursor_dataset_idx" ON "corpus_import_cursor" USING btree ("dataset","year");--> statement-breakpoint
CREATE UNIQUE INDEX "corpus_ocr_queue_page_uq" ON "corpus_ocr_queue" USING btree ("judgment_id","page_no");--> statement-breakpoint
REVOKE ALL ON "corpus_import_cursor", "corpus_ocr_queue" FROM PUBLIC, causedeck_app, causedeck_clerk;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON "corpus_import_cursor" TO causedeck_app;--> statement-breakpoint
GRANT SELECT, INSERT ON "corpus_ocr_queue" TO causedeck_app;--> statement-breakpoint
